#[derive(Debug)]
pub enum Error {
    //IncorrectUsage,
    ReadFile(io::Error),
    ParseTokens { error: String, filepath: PathBuf },
    ParseFile { error: syn_verus::Error, filepath: PathBuf, source_code: String },
    NotFound(String),
    Conflict(String),
    WriteFile(io::Error)
}

impl Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use self::Error::*;

        match self {
            //IncorrectUsage => write!(f, "Usage: dump-syntax path/to/filename.rs"),
            ReadFile(error) => write!(f, "Unable to read file: {}", error),
            ParseTokens { error, filepath } => {
                write!(f, "Unable to tokenize {}: {}", filepath.display(), error)
                    }
                }
            }
        },
        Spec(_) | SpecChecked(_) | Proof(_) | ProofAxiom(_) => {
            func.clone()
        },
    }
}

fn remove_ghost_from_impl_exec_fn(func: &syn_verus::ImplItemFn) -> syn_verus::ImplItemFn {
    match func.sig.mode {
        Exec(_) | Default => {
            match remove_ghost_block(&func.block, &DeghostMode::default()) {
                Some(new_block) => {
                    syn_verus::ImplItemFn {
                        attrs: remove_proof_attr(&func.attrs),
                        vis: func.vis.clone(),
                        defaultness: func.defaultness.clone(),
                        sig: remove_ghost_sig(&func.sig, &DeghostMode::default()).expect("exec fn has non-ghost sig"),
                        block: new_block,
                        semi_token: func.semi_token.clone(),
                    }
                },
                None => {
                    syn_verus::ImplItemFn {
                        attrs: remove_proof_attr(&func.attrs),
                        vis: func.vis.clone(),
                        defaultness: func.defaultness.clone(),
                        sig: remove_ghost_sig(&func.sig, &DeghostMode::default()).expect("exec fn has non-ghost sig"),
                        block: syn_verus::Block { brace_token: func.block.brace_token.clone(), stmts: Vec::new() }, // empty block
                        semi_token: func.semi_token.clone(),
                    }
                }
            }
        },
        Spec(_) | SpecChecked(_) | Proof(_) | ProofAxiom(_) => {
            func.clone()
        },
    }
}
